{
  "root": "root_stack",
  "state": {
    "form": {
      "name": "Alex Doe",
      "title": "Senior Product Manager",
      "company": "FutureTech Inc.",
      "phone": "+1-555-0199",
      "email": "a.doe@futuretech.example.com",
      "website": "https://www.futuretech.example.com"
    }
  },
  "elements": {
    "root_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg",
        "padding": 16
      },
      "children": [
        "title_text",
        "intro_text",
        "form_section",
        "qr_section"
      ]
    },
    "title_text": {
      "type": "Text",
      "props": {
        "text": "Digital Business Card Generator",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This interface allows you to create a vCard QR code from your contact details. Fill in the fields and generate a code that can be scanned to instantly save your information to a phone's contact list."
      },
      "children": []
    },
    "form_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "form_title",
        "name_field",
        "title_field",
        "company_field",
        "phone_field",
        "email_field",
        "website_field",
        "generate_button"
      ]
    },
    "form_title": {
      "type": "Text",
      "props": {
        "text": "1. Enter Your Contact Details",
        "variant": "h3"
      },
      "children": []
    },
    "name_field": {
      "type": "TextField",
      "props": {
        "label": "Name",
        "value": {
          "$bindState": "/form/name"
        }
      },
      "children": []
    },
    "title_field": {
      "type": "TextField",
      "props": {
        "label": "Title",
        "value": {
          "$bindState": "/form/title"
        }
      },
      "children": []
    },
    "company_field": {
      "type": "TextField",
      "props": {
        "label": "Company",
        "value": {
          "$bindState": "/form/company"
        }
      },
      "children": []
    },
    "phone_field": {
      "type": "TextField",
      "props": {
        "label": "Phone (Work)",
        "value": {
          "$bindState": "/form/phone"
        }
      },
      "children": []
    },
    "email_field": {
      "type": "TextField",
      "props": {
        "label": "Email",
        "value": {
          "$bindState": "/form/email"
        }
      },
      "children": []
    },
    "website_field": {
      "type": "TextField",
      "props": {
        "label": "Website",
        "value": {
          "$bindState": "/form/website"
        }
      },
      "children": []
    },
    "generate_button": {
      "type": "Button",
      "props": {
        "label": "Generate QR Code"
      },
      "children": []
    },
    "qr_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "align": "center"
      },
      "children": [
        "qr_title",
        "qr_instruction",
        "qr_icon",
        "save_button"
      ]
    },
    "qr_title": {
      "type": "Text",
      "props": {
        "text": "2. Your vCard QR Code",
        "variant": "h3"
      },
      "children": []
    },
    "qr_instruction": {
      "type": "Text",
      "props": {
        "text": "Scan this QR code with a smartphone camera to add the contact details directly to your address book."
      },
      "children": []
    },
    "qr_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000044_01_1_qr-code.svg"
      },
      "children": []
    },
    "save_button": {
      "type": "Button",
      "props": {
        "label": "Save Image to Device"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://api.qrserver.com/v1/create-qr-code/?size=500x500&data=BEGIN%3AVCARD%0AVERSION%3A3.0%0AN%3ADoe%3BAlex%3B%3B%3B%0AFN%3AAlex%20Doe%0AORG%3AFutureTech%20Inc.%0ATITLE%3ASenior%20Product%20Manager%0ATEL%3BTYPE%3DWORK%2CVOICE%3A%2B1-555-0199%0AEMAIL%3Aa.doe%40futuretech.example.com%0AURL%3Ahttps%3A%2F%2Fwww.futuretech.example.com%0AEND%3AVCARD"
          }
        }
      },
      "children": []
    }
  }
}
